def count_divisors(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

solutions = [36, 56, 135, 351]
results = {}
for n in solutions:
    results[n] = count_divisors(n)

print(results)

